    function Limpiar()
        {
            $(':input').not(':button, :submit, :reset, :hidden, :checkbox, :radio').val('');
            $(':checkbox, :radio').prop('checked', false);
}
        function operateFormatter(value, row, index) {
            return [
                '<a class="Ver" href="javascript:void(0)" title="Ver PDF">',
                '<i class="icon-file-alt"></i>',
                '</a>',
                ].join('');
        }
        
        function operateFormatter1(value, row, index) {
            return [
                '<a class="Ver1" href="javascript:void(0)" title="Ver Historial">',
                '<i class="glyphicon glyphicon-search"></i>',
                '</a>',
                ].join('');
        }
        
        window.operateEvents = {
            'click .Ver': function (e, value, row, index) {
     
             VerPapeleta1(row.ID);
            
            },
            'click .Ver1': function (e, value, row, index) {
     
             VerHistorial(row.ID) 
            }
            
        };
        
            
        function VerPapeleta1(ID)
            {
               var f = document.formularioPDF;
               f.Pagina.value = "Papeletapdf";
               f.Codigo.value = ID;
               f.target = "_blank";
               f.submit();
            }
        
        function VerHistorial(ID)
        {
        $.colorbox({width:"65%", height:"75%", iframe:true, escKey: false,overlayClose: false, href:"mainpage.php?Pagina=Vermovimiento&Accion=muestraVista&AccionLocal=1&Codigo="+ID});
        $('#cboxClose').remove();
        }
        
        function MostrarTablaVisitas() {
            var Anio = $("#cbAnio").val();
            var Mes = $("#cbMes").val();
            var IdMotivo = $("#cbMotivo").val();
            var IdOficina = $("#cbOficina").val();
            var IdEstado = $("#cbEstado").val();
            var IdSituacion = $("#cbSituacion").val();
            var NombreEmpleado = $("#txtNombreEmpleado").val();
            var ApellidoEmpleado = $("#txtApellidoEmpleado").val();
            var RangoFecha = $("#calRango").val();
            var parametro = {url: "mainpage.php?Pagina=<?php echo $PaginaFormulario ?>&Accion=MostrarTablaVisitas&AccionLocal=1&Anio=" + Anio + "&Mes=" + Mes + "&IdMotivo=" + IdMotivo + "&IdOficina=" + IdOficina +  "&IdEstado=" + IdEstado + "&IdSituacion=" + IdSituacion + "&NombreEmpleado=" + NombreEmpleado + "&ApellidoEmpleado=" + ApellidoEmpleado + "&RangoFecha=" + RangoFecha};
            $('#tblVisitas').bootstrapTable('refresh', parametro);
        }       
       
